cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel 1a: compute partial per-channel sum/sumsq across multiple blocks (grid-stride, vectorized)
__global__ void partial_stats_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_out,
    float* __restrict__ sumsq_out,
    int N, int C, int H, int W,
    int blocksPerChannel)
{
    int c = blockIdx.x / blocksPerChannel;
    int chunk = blockIdx.x % blocksPerChannel;
    long HW = (long)H * W;
    long total = (long)N * HW;
    float sum = 0.0f;
    float sumsq = 0.0f;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    if ((HW % 4) == 0) {
        long HW4 = HW / 4;
        long total4 = (long)N * HW4;
        const float4* x4 = reinterpret_cast<const float4*>(x);
        long start = (long)chunk * nthreads + tid;
        long stride = (long)blocksPerChannel * nthreads;
        for (long idx = start; idx < total4; idx += stride) {
            long n = idx / HW4;
            long hw4 = idx % HW4;
            long offset4 = (n * (long)C + c) * HW4 + hw4;
            float4 v = __ldcs(&x4[offset4]);
            sum += v.x + v.y + v.z + v.w;
            sumsq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
        }
    } else {
        long start = (long)chunk * nthreads + tid;
        long stride = (long)blocksPerChannel * nthreads;
        for (long idx = start; idx < total; idx += stride) {
            long n = idx / HW;
            long hw = idx % HW;
            long offset = (n * C + c) * HW + hw;
            float val = __ldcs(&x[offset]);
            sum += val;
            sumsq += val * val;
        }
    }
    // warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = warpSize/2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    __shared__ float warp_sum[32];
    __shared__ float warp_sumsq[32];
    int lane = tid % warpSize;
    int warpId = tid / warpSize;
    if (lane == 0) {
        warp_sum[warpId] = sum;
        warp_sumsq[warpId] = sumsq;
    }
    __syncthreads();
    int numWarps = (nthreads + warpSize - 1) / warpSize;
    if (warpId == 0) {
        sum = (lane < numWarps) ? warp_sum[lane] : 0.0f;
        sumsq = (lane < numWarps) ? warp_sumsq[lane] : 0.0f;
        for (int offset = warpSize/2; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
            sumsq += __shfl_down_sync(mask, sumsq, offset);
        }
        if (lane == 0) {
            atomicAdd(&sum_out[c], sum);
            atomicAdd(&sumsq_out[c], sumsq);
        }
    }
}
// Kernel 1b+1c fused: finalize per-channel mean/var, update running stats, and compute affine scale/shift
__global__ void finalize_stats_and_affine_kernel(
    const float* __restrict__ sum_in,
    const float* __restrict__ sumsq_in,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ scale,
    float* __restrict__ shift,
    long total,
    float momentum,
    float eps,
    int C)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float s = sum_in[c];
    float sq = sumsq_in[c];
    float m = s / (float)total;
    float v = sq / (float)total - m * m;
    if (v < 0.0f) v = 0.0f;
    float unbiased_var = v * (float)total / (float)(total - 1);
    running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * m;
    running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
    float inv_std = rsqrtf(v + eps);
    float sc = weight[c] * inv_std;
    scale[c] = sc;
    shift[c] = bias[c] - m * sc;
}
// Kernel used for eval mode: directly compute scale/shift from running stats
__global__ void compute_affine_from_running_kernel(
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ scale,
    float* __restrict__ shift,
    float eps,
    int C)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float inv_std = rsqrtf(running_var[c] + eps);
    float s = weight[c] * inv_std;
    scale[c] = s;
    shift[c] = bias[c] - running_mean[c] * s;
}
// Kernel 2: normalize using precomputed scale/shift (fused affine transform)
__global__ void bn_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    long HW, int C, int NC)
{
    int nc = blockIdx.y;
    int c = nc % C;
    float s = scale[c];
    float sh = shift[c];
    long base = (long)nc * HW;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)blockDim.x * gridDim.x;
    for (; idx < HW; idx += stride) {
        __stcs(&y[base + idx], __ldcs(&x[base + idx]) * s + sh);
    }
}
__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ x,
    float4* __restrict__ y,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    long HW4, int C, int NC)
{
    int nc = blockIdx.y;
    int c = nc % C;
    float s = scale[c];
    float sh = shift[c];
    long base = (long)nc * HW4;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)blockDim.x * gridDim.x;
    long stride4 = stride * 4;
    long idx0 = idx;
    // Unrolled by 4 to increase instruction-level parallelism and better hide
    // global memory latency for this bandwidth-bound elementwise op.
    for (; idx0 + 3 * stride < HW4; idx0 += stride4) {
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            long id = idx0 + (long)k * stride;
            float4 val = __ldcs(&x[base + id]);
            float4 res;
            res.x = val.x * s + sh;
            res.y = val.y * s + sh;
            res.z = val.z * s + sh;
            res.w = val.w * s + sh;
            __stcs(&y[base + id], res);
        }
    }
    for (; idx0 < HW4; idx0 += stride) {
        float4 val = __ldcs(&x[base + idx0]);
        float4 res;
        res.x = val.x * s + sh;
        res.y = val.y * s + sh;
        res.z = val.z * s + sh;
        res.w = val.w * s + sh;
        __stcs(&y[base + idx0], res);
    }
}
torch::Tensor batch_norm_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    x = x.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    auto y = torch::empty_like(x);
    auto options = x.options();
    auto scale = torch::empty({C}, options);
    auto shift = torch::empty({C}, options);
    if (training) {
        auto sum = torch::zeros({C}, options);
        auto sumsq = torch::zeros({C}, options);
        long HW_ = (long)H * W;
        long total_ = (long)N * HW_;
        int threads = 256;
        long elemsPerThread = (HW_ % 4 == 0) ? 4 : 1;
        long itemsPerBlock = (long)threads * elemsPerThread;
        int blocksPerChannel = (int)((total_ + itemsPerBlock - 1) / itemsPerBlock);
        if (blocksPerChannel < 1) blocksPerChannel = 1;
        if (blocksPerChannel > 64) blocksPerChannel = 64;
        int grid = C * blocksPerChannel;
        partial_stats_kernel<<<grid, threads>>>(
            x.data_ptr<float>(),
            sum.data_ptr<float>(),
            sumsq.data_ptr<float>(),
            N, C, H, W,
            blocksPerChannel
        );
        int fthreads = 256;
        int fblocks = (C + fthreads - 1) / fthreads;
        finalize_stats_and_affine_kernel<<<fblocks, fthreads>>>(
            sum.data_ptr<float>(),
            sumsq.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            scale.data_ptr<float>(),
            shift.data_ptr<float>(),
            total_,
            (float)momentum,
            (float)eps,
            C
        );
    } else {
        int athreads = 256;
        int ablocks = (C + athreads - 1) / athreads;
        compute_affine_from_running_kernel<<<ablocks, athreads>>>(
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            scale.data_ptr<float>(),
            shift.data_ptr<float>(),
            (float)eps,
            C
        );
    }
    long total_elems = (long)N * C * H * W;
    long HW = (long)H * W;
    int NC = N * C;
    int threads2 = 512;
    if ((HW % 4 == 0) && (total_elems % 4 == 0)) {
        long HW4 = HW / 4;
        int blocksx = (int)((HW4 + threads2 - 1) / threads2);
        if (blocksx < 1) blocksx = 1;
        if (blocksx > 65535) blocksx = 65535;
        dim3 grid2(blocksx, NC);
        bn_normalize_kernel_vec4<<<grid2, threads2>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            scale.data_ptr<float>(),
            shift.data_ptr<float>(),
            HW4, C, NC
        );
    } else {
        int blocksx = (int)((HW + threads2 - 1) / threads2);
        if (blocksx < 1) blocksx = 1;
        if (blocksx > 65535) blocksx = 65535;
        dim3 grid2(blocksx, NC);
        bn_normalize_kernel<<<grid2, threads2>>>(
            x.data_ptr<float>(),
            y.data_ptr<float>(),
            scale.data_ptr<float>(),
            shift.data_ptr<float>(),
            HW, C, NC
        );
    }
    return y;
    return y;
}
